import{_ as t,o as i,c as a,an as s}from"./chunks/framework.BMe1Ravt.js";const n="/Kraken.jl/v0.2.2/assets/gpu-certification.BefYUZJZ.png",u=JSON.parse('{"title":"GPU efficiency certification — BGK D2Q9 CUDA F64","description":"","frontmatter":{},"headers":[],"relativePath":"users/benchmarks/gpu-certification.md","filePath":"users/benchmarks/gpu-certification.md","lastUpdated":null}'),o={name:"users/benchmarks/gpu-certification.md"};function r(l,e,d,c,h,p){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="GPU-efficiency-certification-—-BGK-D2Q9-CUDA-F64" tabindex="-1">GPU efficiency certification — BGK D2Q9 CUDA F64 <a class="header-anchor" href="#GPU-efficiency-certification-—-BGK-D2Q9-CUDA-F64" aria-label="Permalink to &quot;GPU efficiency certification — BGK D2Q9 CUDA F64 {#GPU-efficiency-certification-—-BGK-D2Q9-CUDA-F64}&quot;">​</a></h1><p>Single-GPU throughput of the Newtonian BGK D2Q9 solver in <strong>CUDA Float64</strong> (Taylor–Green driver, <code>run_taylor_green_2d</code>). Kraken sustains <strong>3461 MLUPS</strong> at <code>N = 2048</code> on an <strong>A100-40GB</strong>, reaching <strong>0.68</strong> of the memory-bandwidth roofline and <strong>0.74</strong> of the published Palabos single-GPU F64 number — comfortably clearing the <strong>≥ 0.5 of roofline</strong> gate.</p><p><img src="'+n+`" alt=""></p><h2 id="Result" tabindex="-1">Result <a class="header-anchor" href="#Result" aria-label="Permalink to &quot;Result {#Result}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Reference</th><th style="text-align:right;">MLUPS</th><th style="text-align:right;">Kraken / ref</th><th style="text-align:right;">Type</th></tr></thead><tbody><tr><td style="text-align:right;">A100-40GB roofline (1.555 TB/s)</td><td style="text-align:right;">5115</td><td style="text-align:right;"><strong>0.68</strong></td><td style="text-align:right;">bandwidth ceiling</td></tr><tr><td style="text-align:right;">A100-80GB roofline (2.039 TB/s)</td><td style="text-align:right;">6707</td><td style="text-align:right;"><strong>0.52</strong></td><td style="text-align:right;">bandwidth ceiling</td></tr><tr><td style="text-align:right;">Palabos, single-GPU F64 D3Q19 TRT</td><td style="text-align:right;">4656</td><td style="text-align:right;"><strong>0.74</strong></td><td style="text-align:right;">published real code</td></tr></tbody></table><p><strong>Verdict: PASS.</strong> On the applicable A100-40GB roofline Kraken reaches 0.68 of the memory-bandwidth limit and 0.74 of the Palabos single-GPU F64 number — same neighbourhood as an established production LBM code. Even against the stricter 80 GB ceiling the ratio is 0.52, so the pass is robust to the bandwidth assumption. The Palabos figure is ~73 % of A100 FP64 peak (Latt et al., <em>Comput. Math. Appl.</em> 2021; PASC &#39;22); the H100 roofline (11020 MLUPS) is context only — the run was on an A100.</p><h2 id="Method" tabindex="-1">Method <a class="header-anchor" href="#Method" aria-label="Permalink to &quot;Method {#Method}&quot;">​</a></h2><p>The metric is sustained MLUPS measured over 1000 steps after a discarded warm-up on an <code>N × N</code> periodic domain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MLUPS = N² · steps / wallclock_s / 1e6</span></span></code></pre></div><p>Best sustained throughput was 3461 MLUPS at <code>N = 2048</code> (3084 MLUPS at <code>N = 1024</code>).</p><p><strong>Roofline.</strong> LBM is memory-bandwidth bound: a D2Q9 BGK step in Float64 moves 9 populations in and 9 out, <code>2 × 19 × sizeof(Float64) = 304 bytes/update</code>, so the hard upper bound is <code>MLUPS_ceiling = peak_BW / 304 / 1e6</code>. No F64 D2Q9 kernel can exceed it.</p><p><strong>Environment.</strong> Aqua (QUT) node <code>gpu0n009</code>, NVIDIA A100-40GB (HBM2e, 1.555 TB/s peak), CUDA Float64. The 40 GB roofline is the applicable ceiling; the 80 GB figure is a stricter lower-bound reference.</p><h2 id="Caveats" tabindex="-1">Caveats <a class="header-anchor" href="#Caveats" aria-label="Permalink to &quot;Caveats {#Caveats}&quot;">​</a></h2><ul><li><p><strong>GPU variant confirmed post-hoc via PBS node resources, not the run log.</strong> The driver did not record the device; the A100-40GB identity was read from <code>pbsnodes gpu0n009</code>. A future tweak is to print <code>CUDA.versioninfo()</code> / <code>CUDA.device()</code> into the run log so the exact GPU and roofline are locked by the run itself.</p></li><li><p><strong>Single-GPU, bandwidth-bound figure.</strong> This certifies single-GPU throughput against the memory roofline; it is not a multi-GPU or weak/strong-scaling result.</p></li></ul><h2 id="Reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#Reproduce" aria-label="Permalink to &quot;Reproduce {#Reproduce}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Aqua (CUDA F64) — runs the certification sweep and writes the CSV:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/certification/cavity_bgk_cuda/run_certification.jl</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># regenerate the figure:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">conda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kraken-v0-3-figures</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/certification/plot_certification.py</span></span></code></pre></div><p>Data: <code>benchmarks/results/certification_a100.csv</code>. Reference derivation: <code>bench/certification/E1_REFERENCE.md</code>. F32 codes such as FluidX3D (Lehmann, arXiv:2112.08926) are <strong>not</strong> comparable to this F64 gate — single precision moves half the bytes per update.</p>`,17)])])}const f=t(o,[["render",r]]);export{u as __pageData,f as default};
